def transform(grid):
    """Recolor every cell in the topmost non-background object to 0."""
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    if not rows:
        return out
    top = min(rows)
    for c, value in enumerate(grid[top]):
        if value != bg:
            out[top][c] = 0
    return out

